import fs from 'node:fs';
import path from 'node:path';
import { RuleLoader } from '../rules/loader.js';

export function generateRulesMarkdown(): string {
  const { dpdpMap, rules } = RuleLoader.loadRules();

  const lines: string[] = [];
  lines.push('# DPDP-Audit Rules & Compliance Framework Reference');
  lines.push('');
  lines.push(
    'This document is auto-generated by DPDP-Audit. It details all static analysis checks, compliance rules, and direct legal mappings to the **Digital Personal Data Protection Act 2023 (Act No. 22 of 2023)** and **Digital Personal Data Protection Rules 2025**.'
  );
  lines.push('');
  lines.push('## Executive Rule Statistics');
  lines.push('');
  lines.push(`- **Total Registered Rules**: ${rules.length}`);
  lines.push(`- **Mapped DPDP Legal Provisions**: ${Object.keys(dpdpMap).length}`);

  const byCat: Record<string, number> = {};
  const bySev: Record<string, number> = {};
  for (const r of rules) {
    byCat[r.category] = (byCat[r.category] || 0) + 1;
    bySev[r.severity] = (bySev[r.severity] || 0) + 1;
  }

  lines.push('');
  lines.push('### Breakdown by Category');
  lines.push('| Category | Rule Count | Scope |');
  lines.push('| :--- | :--- | :--- |');
  lines.push(`| **Logging** | ${byCat.logging || 0} | PII in console/loggers, req.body dumping, stack traces, log retention |`);
  lines.push(`| **Storage** | ${byCat.storage || 0} | Plaintext passwords, weak hashing, weak ciphers, hardcoded secrets, cookies, localStorage |`);
  lines.push(`| **Transfer** | ${byCat.transfer || 0} | Insecure HTTP, disabled TLS verification, ad/analytics SDK leakage, cross-border |`);
  lines.push(`| **Exposure** | ${byCat.exposure || 0} | Full entity leaks, missing route auth, IDOR, verbose errors, CORS wildcard, public buckets, open DB ports |`);
  lines.push(`| **Config** | ${byCat.config || 0} | Committed .env, Docker root execution, no healthcheck, excessive privileges, IAM wildcards |`);
  lines.push(`| **Lifecycle** | ${byCat.lifecycle || 0} | Right to erasure (deletion), right to access (export), right to correction, TTL, DPO contact |`);
  lines.push(`| **Children** | ${byCat.children || 0} | Missing age gate, child tracking/profiling, lack of verifiable parental consent |`);
  lines.push(`| **Breach Readiness** | ${byCat.breach || 0} | Audit trails on sensitive data access, automated breach alerting hooks |`);
  lines.push('');

  lines.push('### Breakdown by Severity');
  lines.push('| Severity | Rule Count | Risk Weight |');
  lines.push('| :--- | :--- | :--- |');
  lines.push(`| **Critical** | ${bySev.critical || 0} | Direct high-probability breach or critical penalty risk (Up to ₹250 Cr) |`);
  lines.push(`| **High** | ${bySev.high || 0} | Substantial privacy exposure, unprotected storage or transmission |`);
  lines.push(`| **Medium** | ${bySev.medium || 0} | Compliance gap, missing lifecycle control or excessive data retention |`);
  lines.push(`| **Low** | ${bySev.low || 0} | Defense-in-depth posture or informational config hygiene |`);
  lines.push('');

  lines.push('## Legal Provision Mapping (dpdp-map.yaml)');
  lines.push('| Key | Law | Provision | Title | Statutory Penalty Clause |');
  lines.push('| :--- | :--- | :--- | :--- | :--- |');
  for (const [key, ref] of Object.entries(dpdpMap)) {
    lines.push(`| \`${key}\` | ${ref.law} | **${ref.provision}** | ${ref.title} | ${ref.penaltyClause || 'Schedule Item 4: Up to ₹50 Cr'} |`);
  }
  lines.push('');

  lines.push('## Complete Catalog of Checks & Rules');
  lines.push('');

  const categories = ['logging', 'storage', 'transfer', 'exposure', 'config', 'lifecycle', 'children', 'breach'] as const;

  for (const cat of categories) {
    const catRules = rules.filter((r) => r.category === cat);
    lines.push(`### Category: ${cat.toUpperCase()}`);
    lines.push('');

    for (const r of catRules) {
      const ref = dpdpMap[r.dpdpRef];
      lines.push(`#### \`[${r.id}]\` ${r.title}`);
      lines.push('');
      lines.push(`- **Severity**: \`${r.severity.toUpperCase()}\``);
      lines.push(`- **DPDP Statutory Reference**: **${ref ? ref.provision : r.dpdpRef}** (${ref ? ref.law : ''}) - *${ref ? ref.title : ''}*`);
      lines.push(`- **Data Flow State**: \`${r.dataFlow}\``);
      lines.push(`- **Target Files**: \`${r.targetFiles.join(', ')}\` (Engine: \`${r.targetType.toUpperCase()}\`)`);
      lines.push(`- **Monitored PII Classes**: ${r.piiTypes.length ? r.piiTypes.map((p) => `\`${p}\``).join(', ') : '*Config / Infrastructure*'}`);
      lines.push(`- **Statutory Summary**: ${ref ? ref.summary : 'N/A'}`);
      lines.push(`- **Description**: ${r.description}`);
      lines.push(`- **Recommended Remediation**: ${r.remediation}`);
      if (r.patchTemplate) {
        lines.push(`- **Auto-Fix Available**: Yes (\`${r.patchTemplate}\`)`);
      }
      lines.push('');
    }
  }

  return lines.join('\n');
}

export function run(): void {
  const content = generateRulesMarkdown();
  const docsDir = path.resolve(process.cwd(), 'docs');
  if (!fs.existsSync(docsDir)) {
    fs.mkdirSync(docsDir, { recursive: true });
  }
  const outPath = path.join(docsDir, 'RULES.md');
  fs.writeFileSync(outPath, content, 'utf8');
  console.log(`Successfully generated ${outPath} with ${RuleLoader.loadRules().rules.length} rules.`);
}

if (import.meta.url === `file://${process.argv[1]}`) {
  run();
}
